package org.bedrockresearch.movement;

/** Full solver boundary. The delivered default deliberately reports missing native logic. */
@FunctionalInterface
public interface AuthoritativeSimulator {
    SimulationResult simulate(AuthoritativeState before, InputFrame input, WorldSnapshot world);

    static AuthoritativeSimulator unavailable() {
        return (before, input, world) -> new SimulationResult.Unavailable(java.util.List.of(
            "Complete BDS player simulation and mechanic dispatch have not been reconstructed.",
            "No movement verdict or correction is generated by the partial port."));
    }
}
